script:
Import-Module WebAdministration -ErrorAction Ignore
$site = 'SaltmarshAdmin'
$pool = 'SaltmarshAdmin'
$root = 'C:\inetpub\saltmarsh\admin'
New-Item -ItemType Directory -Force -Path $root | Out-Null
if (-not (Test-Path "IIS:\AppPools\$pool")) { New-WebAppPool -Name $pool | Out-Null }
if (-not (Get-Website -Name $site -ErrorAction Ignore)) {
    New-Website -Name $site -PhysicalPath $root -Port 8080 -ApplicationPool $pool | Out-Null
} else {
    Set-ItemProperty -Path "IIS:\Sites\$site" -Name physicalPath -Value $root -ErrorAction Ignore
}
$page = @'
<!doctype html>
<html><body><h1>Saltmarsh internal console</h1></body></html>
'@
Set-Content -Path (Join-Path $root 'default.html') -Value $page -Encoding ascii
if (-not (Get-NetFirewallRule -Name 'SaltmarshAdmin' -ErrorAction Ignore)) {
    New-NetFirewallRule -Name 'SaltmarshAdmin' -DisplayName 'SaltmarshAdmin' `
        -Direction Inbound -Protocol TCP -LocalPort 8080 -Action Allow -Profile Any | Out-Null
}
Start-Website -Name $site -ErrorAction Ignore
Write-Output 'admin console site planted'
